var CatalogLogic={
 available(row,inst){return inst==='common'?['vi','vi2','va','vc'].every(x=>row.instruments.includes(x)):inst==='cello-only'?row.instruments.length===1&&row.instruments[0]==='vc':row.instruments.includes(inst)},
 filter(rows,f){const words=(f.q||'').toLowerCase().trim().split(/\s+/).filter(Boolean);return rows.filter(r=>this.available(r,f.instrument||'vi')&&['category','attack','release','vibrato','length','mode'].every(k=>!f[k]||r[k]===f[k])&&words.every(w=>[r.caption,r.zh,r.en,r.token,...r.aliases].join(' ').toLowerCase().includes(w)))},
 options(rows,key,inst){return [...new Set(rows.filter(r=>this.available(r,inst)).map(r=>r[key]).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'en'))}
};

function filter(f) { return CatalogLogic.filter(rows,f); }
function options(key, instrument) {
    var vals=CatalogLogic.options(rows,key,instrument);
    return [{text:"All",value:""}].concat(vals.map(function(v) { return {text:modeNames[v]||v,value:v}; }));
}
function knownRoute(id,caption,token) {
    for (var i=0;i<rows.length;++i) {
        var r=rows[i];
        if (r.id===id && r.caption===caption && r.token===token) return r;
    }
    return null;
}
function isKnown(id,caption,token) { return knownRoute(id,caption,token)!==null; }

var modeNames={"固定音色":"Fixed articulation","自动速度":"Automatic speed","连续交叉渐变":"Continuous blend","速度 + 交叉渐变":"Speed + blend","自动交替序列":"Alternating sequence"};
